        stack, current_group = [], ''
        in_brackets = False
        for char in paren_string:
            if char == '(':
                stack.append(char)
                current_group += char
            elif char == ')':
                if not stack:
                    # closing parenthesis, add current group to result and reset stack
                    result.append(current_group)
                    current_group = ''
                elif in_brackets:
                    # not a closing parenthesis, ignore
                    continue
                else:
                    in_brackets = True
            elif char.isspace():
                # ignore all whitespace
                continue
            else:
                break
        if stack:
            # closing parenthesis, add current group to result and reset stack
            result.append(current_group)
            current_group = ''
        else:
            break
    return result

