def change_base(x: int, base: int) -> str:
    # Handle the case where base is less than 2
    if base < 2:
        return "Invalid base, must be greater than 1"

    # Initialize an empty dictionary to store the base-10 value of each digit
    digit_values = {}

    # Calculate the base-10 representation of the number
    temp = x
    while temp > 0:
        temp, remainder = divmod(temp, base)
        digit_values[remainder] = digit_values.get(remainder, 0) + 1
    digit_values = {str(i): count for i, count in digit_values.items() for _ in range(count)}

    # Convert the digit values to string representation
    result = ""
    for i, digit in digit_values.items():
        result += digit * base ** digit_values[i]

    return result

