def fizz_buzz(n):
    """Returns the nth number in the Fibonacci sequence. A number is F(n) if it is divisible by both 3 and 5."""
    if n <= 0:
        return "Input should be a positive integer."
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        while True:
            fib_prev = 0
            fib_curr = 1
            count = 2
            while count < n:
                if (fib_prev + fib_curr) % 15 == 0:
                    return fib_prev + fib_curr
                fib_prev, fib_curr = fib_curr, fib_prev + fib_curr
                count += 1

# Example usage:
