def monotonic(lst: List[int]) -> bool:
    if len(lst) < 2:
        return True
    decreasing = all(x < y for x, y in zip(lst, lst[1:])
                        if x < y)
    increasing = all(x > y for x, y in zip(lst, lst[1:])
                        if x > y)
    return decreasing or increasing
