def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.

    Args:
        n (int): A non-negative integer.

    Returns:
        list: A list of the first n prime numbers that are less than n.
    """
    def is_prime(num):
        """Check if a number is prime."""
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_list = []
    num_count = 0
    for i in range(2, n + 1):
        if is_prime(i):
            prime_list.append(i)
            num_count += 1
            if num_count == n:
                return prime_list
    return []

