def even_odd_palindrome(n):
    """
    Given a positive integer n, return a tuple that has the number of even and odd integer palindromes that fall within the range(1, n), inclusive.

    Args:
        n (int): A positive integer.

    Returns:
        tuple: A tuple containing the number of even and odd integer palindromes, respectively.
    """
    count = 0
    for i in range(1, int(n**0.5) + 1):
        # Check if the number is a palindrome
        if str(i) == str(i)[::-1]:
            if i + 1 % 2 == 0:
                count += 1
        if i > n // 2:
            break
    return count, (n - count)
