def count_nums(arr):
    """
    Returns the number of elements in the array that have a sum of digits > 0.
    If a number is negative, its first signed digit is used first.
    """
    count = 0
    for num in arr:
        if num < 0:
            cur_digit = 1
            while num > 0:
                digit_sum = num % 10
                if digit_sum > 0:
                    count += 1
                num //= 10
                cur_digit += 1
        else:
            while num > 0:
                digit_sum = num % 10
                if digit_sum > 0:
                    count += 1
                num //= 10
    return count
