def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Initialize an empty dictionary to store the frequency of each letter
    freq_dict = {}

    # Split the input string into a list of characters
    chars = list(test)

    # Count the frequency of each character
    for char in chars:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1

    # Find the maximum frequency
    max_freq = max(freq_dict.values())

    # Create a list of characters with their frequency
    freq_list = [[char, freq] for char, freq in freq_dict.items()]

    # Sort the list in descending order of frequency
    freq_list.sort(key=lambda x: x[1], reverse=True)

    # Group the characters by frequency
    grouped_freq = {}
    for char, freq in freq_list:
        if freq not in grouped_freq:
            grouped_freq[freq] = [char]
        else:
            grouped_freq[freq].append(char)

    # Return the dictionary of characters with the most suppression
    return dict(grouped_freq)

