def minPath(grid, k):
    N = len(grid)
    def bfs(start, visited):
        queue = [(start, [start])]
        visited[start] = True
        while queue:
            (x, y), path = queue.pop(0)
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < N and not visited[nx][ny]:
                    queue.append(((nx, ny), path + [grid[nx][ny]]))
                    visited[nx][ny] = True
        return path

    def dfs(grid, k, x, y, visited):
        if k == 1:
            return [x, y]
        path = []
        if x == N - 1 and y == N - 1:
            return path
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and (nx, ny) not in visited:
                complement = dfs(grid, k - 1, nx, ny, visited)
                if complement:
                    path.append(grid[nx][ny])
                    path.extend(complement)
        return path

    return dfs(grid, k, 0, 0, {})

