def simplify(x, n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    def gcd_fraction(numerator, denominator):
        return gcd(numerator, denominator)

    numerator = int(x.split('/')[0].strip())
    denominator = int(n.split('/')[1].strip())

    result_gcd = gcd_fraction(numerator, denominator)
    result = lcm(result_gcd, int(n) // result_gcd)

    # Calculate the new numerator and denominator
    new_numerator = numerator * int(n) // result
    new_denominator = denominator * int(n) // result

    return new_numerator == new_denominator == 1
```

