def simplify(x, n):
    def gcd(a, b):
        """Calculate the greatest common divisor of a and b using Euclid's algorithm"""
        while b:
            a, b = b, a % b
        return a

    def gcd_two_numbers(a, b):
        """Calculate the greatest common divisor of two numbers using Euclid's algorithm"""
        while b:
            a, b = b, a % b
        return a

    def evaluate_expression(x):
        """Evaluate the expression x * n"""
        def evaluate(x, n):
            """Evaluate the expression by multiplying x by n"""
            result = 0
            for i in range(len(str(x)) + 1):
                power = len(str(x)) - i
                if i <= n and x > 0:  # if i is within the valid range of the x and n
                    result += int(str(x)[i] * (10 ** power))
            return result
        numerator = evaluate(x, n)
        denominator = n
        if gcd_two_numbers(numerator, denominator) == 1:
            return numerator // denominator
        else:
            return False

    return evaluate_expression(x) <= 1
