import math

def bf(planet1, planet2):
    """
    Returns a tuple of planets between the orbits of planet1 and planet2, sorted by proximity.

    Args:
        planet1 (str): The name of the first planet.
        planet2 (str): The name of the second planet.

    Returns:
        tuple: A tuple of planet names between the orbits of planet1 and planet2, sorted by proximity.
    """
    def distance_to_sun(planet):
        # assume planet1 is the starting planet
        return math.sqrt((float(planet) - 1)**2 + 1)

    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets:
        return ()
    if planet2 not in planets:
        return ()

    orbit_diff = distance_to_sun(planet2) - distance_to_sun(planet1)
    min_planet = planets[planets.index(planet1) + (planet2 - planet1) // 2]
    max_planet = planets[planets.index(planet2) + (planet1 - planet2) // 2]

    result = [planet for planet in planets if min_planet <= distance_to_sun(planet) <= max_planet]
    return tuple(sorted(result))
